// biome-ignore-all lint/a11y/useSemanticElements: the frame and the addon are divs with role="group" so they can wrap an input, a textarea, or a button set without changing the markup per control.
// biome-ignore-all lint/a11y/useKeyWithClickEvents: the click handler only moves focus into the control; keyboard users tab there directly, so no key equivalent is owed.
"use client";

import { cva, type VariantProps } from "class-variance-authority";
import { AnimatePresence, useIsPresent, usePresence } from "motion/react";
import type * as React from "react";
import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { Button } from "../button";
import { Input } from "../input";
import { createGroupPositions, type GroupPosition } from "../lib/button-group-layout";
import { cn } from "../lib/cn";
import { useStateColor } from "../lib/css-motion";
import { createInlineEntrance } from "../lib/inline-entrance";
import { createInlinePresence } from "../lib/inline-presence";
import { createMeasuredGeometry, type GeometryDestination, naturalGeometry } from "../lib/measured-geometry";
import { bindMotionParameters, geometryCompact, layoutCompact, motionLimits } from "../lib/motion";
import {
  createPresentationScope,
  documentPresentation,
  MotionPresentation,
  usePresentationScope,
} from "../lib/motion-presence";
import { useMotionHostRef } from "../lib/motion-ref";
import type { MotionRevision } from "../lib/motion-transaction";
import { useCadenceMotion } from "../lib/provider";
import { useNumberPresentation } from "../lib/use-number-presentation";
import { useTextPresentation } from "../lib/use-text-presentation";
import { Textarea } from "../textarea";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
const subscribe = () => () => {};

type Scope = ReturnType<typeof createPresentationScope>;
const Group = createContext<{
  scope: Scope;
  present: boolean;
  request(): void;
  attach(
    host: HTMLElement,
    project: (from: GroupPosition, to: GroupPosition, revision: MotionRevision, animate: boolean) => void,
  ): () => void;
} | null>(null);

export interface InputGroupProps extends React.ComponentProps<"div"> {}

/**
 * A field with furniture: a prefix, a unit, a button, a keyboard hint.
 *
 * The frame is the presentation owner for insertion, surface paint and its own
 * block size; the controls keep native editing, caret and selection. Membership
 * is retained only for keyed children, so a keyed addon can fade out while an
 * unkeyed one is removed immediately — the group never invents an identity.
 */
function InputGroup({ className, style, children, ...props }: InputGroupProps) {
  const { node } = useMotionHostRef<HTMLDivElement>(props.ref);
  const cm = useCadenceMotion(node);
  // Caller palettes are unverified; unknown paint settles at its target.
  // The frame paints its own chrome. Foreground belongs to the control and the
  // display text, so this list never claims `color`.
  const paint = useStateColor(
    node,
    cm,
    [
      "background-color",
      "border-top-color",
      "border-right-color",
      "border-bottom-color",
      "border-left-color",
      "box-shadow",
    ],
    {
      readability: surfaceVerified(className, style) ? "verified" : "immediate",
    },
  );
  const parent = usePresentationScope();
  const present = useIsPresent();
  const [scope] = useState(() => createPresentationScope(node));
  const [geometry] = useState(() => createMeasuredGeometry(scope.transaction));
  // Each addon projects its own retained position; the frame only publishes the
  // committed boxes, so no component writes another component's transform.
  const projections = useRef(
    new Map<
      HTMLElement,
      (from: GroupPosition, to: GroupPosition, revision: MotionRevision, animate: boolean) => void
    >(),
  );
  const hydrated = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const firstHydration = useRef(hydrated);
  const consumed = useRef(false);
  const entrance = useRef<ReturnType<typeof createInlineEntrance> | null>(null);
  const release = useRef<(() => void) | null>(null);
  const registered = useRef<HTMLDivElement | null>(null);
  const boxes = useRef(new Map<HTMLElement, GroupPosition>());
  const signature = useRef("");
  const captured = useRef(0);
  const alive = useRef(true);
  const pending = useRef(false);
  const flush = useRef(() => {});
  const members = Children.toArray(children);
  let keyed = true;
  Children.forEach(children, (child) => {
    if (isValidElement(child) && child.key === null) keyed = false;
  });
  const request = useRef(() => {
    if (pending.current) return;
    pending.current = true;
    queueMicrotask(() => {
      pending.current = false;
      if (alive.current) flush.current();
    });
  });
  useEffect(() => {
    if (!parent && node.current) documentPresentation(node.current.ownerDocument).presented = true;
  }, [parent, node]);
  committed(() => {
    const host = node.current;
    if (!host) return;
    const baseline = parent ?? documentPresentation(host.ownerDocument);
    if (!entrance.current) entrance.current = createInlineEntrance(host);
    const visible = host.checkVisibility
      ? host.checkVisibility({ visibilityProperty: true, contentVisibilityAuto: true })
      : host.getClientRects().length > 0;
    // A presenting parent owns this entrance; an unusable or hidden host keeps
    // native paint instead of fading an already-visible frame.
    const inherited =
      !visible ||
      Boolean(host.closest('[hidden],[inert],[aria-hidden="true"]')) ||
      !baseline.available() ||
      baseline.node?.current?.hasAttribute("data-starting-style");
    entrance.current.commit({
      present,
      cm: inherited ? { ...cm, timeScale: 0 } : cm,
      enter: !consumed.current && !firstHydration.current && baseline.presented && !inherited,
    });
    consumed.current = true;
    if (registered.current !== host) {
      release.current?.();
      release.current = null;
      registered.current = host;
      release.current = geometry.register({
        host: node,
        content: host,
        // The inline size is parent-owned (`w-full`); only the block axis is an
        // owned, addon/content-driven frame extent.
        axes: ["height"],
        observeChildren: true,
        measure: (reason) => frameHeight(host, reason, captured.current),
      });
    }
    flush.current();
  });
  flush.current = () => {
    const host = node.current;
    if (!host) return;
    const tracked = [...host.children].filter(
      (child): child is HTMLElement =>
        child instanceof HTMLElement &&
        ["input-group-addon", "input-group-button"].includes(child.getAttribute("data-slot") ?? "") &&
        !child.hasAttribute("data-ending-style") &&
        !child.hasAttribute("hidden"),
    );
    const next = JSON.stringify([
      cm.mode,
      cm.timeScale,
      cm.scope.signature,
      present,
      tracked.map((child) => [
        child.getAttribute("data-slot"),
        child.getAttribute("data-align"),
        child.className,
        child.textContent,
      ]),
    ]);
    const previous = signature.current;
    signature.current = next;
    const changed = previous !== "" && previous !== next;
    const available =
      present &&
      scope.available() &&
      captured.current === 0 &&
      !editor(host) &&
      host.children.length + 1 <= motionLimits.collectionVisuals;
    const parameters = cm.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
    if (parameters.kind !== "geometry") return;
    const measured = new Map<HTMLElement, GroupPosition>();
    if (available) {
      const root = host.getBoundingClientRect();
      for (const child of tracked) {
        const box = child.getBoundingClientRect();
        measured.set(child, { x: box.x - root.x, y: box.y - root.y, width: box.width, height: box.height });
      }
    }
    const revision = scope.transaction.revision("content", next, host);
    geometry.commit(revision, {
      reduced: cm.reduced,
      transition: parameters.transition,
      available,
    });
    // Every commit publishes the current revision, so a retained addon settles
    // its own projection instead of keeping a superseded one alive.
    for (const [element, project] of projections.current) {
      const to = measured.get(element) ?? boxes.current.get(element),
        from = boxes.current.get(element) ?? to;
      if (to && from) project(from, to, revision, available && changed);
    }
    if (available) boxes.current = measured;
  };
  committed(() => {
    const host = node.current;
    const doc = host?.ownerDocument;
    if (!doc || !host) return;
    // Frame geometry yields to the editor: a pointer, a composition or a focused
    // editor settles the frame before paint instead of moving its content box.
    const hold = () => {
      captured.current++;
      geometry.settle();
    };
    const release_ = () => {
      captured.current = Math.max(0, captured.current - 1);
      request.current();
    };
    const focus = () => {
      if (editor(host)) geometry.settle();
      request.current();
    };
    const passive = () => {
      signature.current = "";
      geometry.settle();
      request.current();
    };
    host.addEventListener("pointerdown", hold, true);
    host.addEventListener("compositionstart", hold, true);
    host.addEventListener("focusin", focus, true);
    host.addEventListener("focusout", release_, true);
    doc.addEventListener("pointerup", release_, true);
    doc.addEventListener("pointercancel", release_, true);
    doc.addEventListener("compositionend", release_, true);
    doc.addEventListener("scroll", passive, true);
    doc.defaultView?.addEventListener("resize", passive);
    return () => {
      host.removeEventListener("pointerdown", hold, true);
      host.removeEventListener("compositionstart", hold, true);
      host.removeEventListener("focusin", focus, true);
      host.removeEventListener("focusout", release_, true);
      doc.removeEventListener("pointerup", release_, true);
      doc.removeEventListener("pointercancel", release_, true);
      doc.removeEventListener("compositionend", release_, true);
      doc.removeEventListener("scroll", passive, true);
      doc.defaultView?.removeEventListener("resize", passive);
    };
  }, []);
  committed(() => {
    alive.current = true;
    return () => {
      alive.current = false;
      entrance.current?.dispose();
      entrance.current = null;
      release.current?.();
      release.current = null;
      geometry.dispose();
      boxes.current.clear();
      projections.current.clear();
      registered.current = null;
    };
  }, []);
  return (
    <MotionPresentation scope={scope}>
      <Group.Provider
        value={{
          scope,
          present,
          request: request.current,
          attach(host, project) {
            projections.current.set(host, project);
            return () => projections.current.delete(host);
          },
        }}
      >
        <div
          data-slot="input-group"
          role="group"
          {...props}
          {...paint}
          data-motion={cm.mode}
          className={cn(
            "group/input-group relative flex w-full min-w-0 items-center rounded-md border border-input shadow-xs outline-none dark:bg-input/30",
            "h-9 has-[>textarea]:h-auto",

            // Alignment decides which side the control gives up padding on.
            "has-[>[data-align=inline-start]]:[&>input]:pl-2",
            "has-[>[data-align=inline-end]]:[&>input]:pr-2",
            "has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-start]]:[&>input]:pb-3",
            "has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-end]]:[&>input]:pt-3",

            // Focus and invalid state are borrowed from the control, not owned here.
            "has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-[3px] has-[[data-slot=input-group-control]:focus-visible]:ring-ring/50",
            "has-[[data-slot][aria-invalid=true]]:border-destructive has-[[data-slot][aria-invalid=true]]:ring-destructive/20 dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40",

            className,
          )}
          style={{ ...paint.style, ...style }}
        >
          {keyed ? <AnimatePresence initial={false}>{members}</AnimatePresence> : members}
        </div>
      </Group.Provider>
    </MotionPresentation>
  );
}

/** Unknown palettes commit at their target rather than through unreadable paint. */
function surfaceVerified(className: InputGroupProps["className"], style: InputGroupProps["style"]) {
  if (typeof className === "function" || typeof style === "function") return false;
  if (
    Object.keys(style ?? {}).some((key) =>
      /color|background|shadow|opacity|filter|blend|^--(?!motion-|cadence-|ease-)/i.test(key),
    )
  )
    return false;
  return !(typeof className === "string" ? className : "")
    .split(/\s+/)
    .some(
      (name) =>
        /(?:^|:)(?:bg-|text-|border-|shadow-|ring-)/.test(name) &&
        !/(?:^|:)(?:border-(?:input|ring|destructive)|shadow-xs|bg-input\/30|ring-(?:ring\/50|destructive\/(?:20|40)|\[3px\]))$/.test(
          name,
        ),
    );
}

const inputGroupAddonVariants = cva(
  "flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-sm font-medium text-muted-foreground select-none group-data-[disabled=true]/input-group:opacity-50 [&>kbd]:rounded-[calc(var(--radius)-5px)] [&>svg:not([class*='size-'])]:size-4",
  {
    variants: {
      align: {
        "inline-start": "order-first pl-3 has-[>button]:ml-[-0.45rem] has-[>kbd]:ml-[-0.35rem]",
        "inline-end": "order-last pr-3 has-[>button]:mr-[-0.45rem] has-[>kbd]:mr-[-0.35rem]",
        "block-start":
          "order-first w-full justify-start px-3 pt-3 group-has-[>input]/input-group:pt-2.5 [.border-b]:pb-3",
        "block-end": "order-last w-full justify-start px-3 pb-3 group-has-[>input]/input-group:pb-2.5 [.border-t]:pt-3",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  },
);

export interface InputGroupAddonProps
  extends React.ComponentProps<"div">,
    VariantProps<typeof inputGroupAddonVariants> {}

/**
 * The furniture around the control. Clicking it focuses the input — unless the
 * click landed on a button, which has its own job, or the caller cancelled it.
 *
 * Presence is its own opacity channel: a later-inserted addon fades in, a
 * retained one fades out, and the frame's geometry stays the group's business.
 */
function InputGroupAddon({ className, align = "inline-start", children, onClick, ...props }: InputGroupAddonProps) {
  const { node, ref } = useMotionHostRef<HTMLDivElement>(props.ref);
  const cm = useCadenceMotion(node);
  const group = useContext(Group);
  const [present, remove] = usePresence();
  const delivery = useRef({ ready: false, pending: false, present, complete: remove });
  useInsertionEffect(() => {
    Object.assign(delivery.current, { ready: false, present, complete: remove });
  });
  useEffect(() => {
    const entry = delivery.current;
    entry.ready = true;
    // A zero-clock layout completion precedes the parent's presence bookkeeping.
    if (entry.pending && !entry.present) entry.complete?.();
    entry.pending = false;
  });
  const hydrated = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const firstHydration = useRef(hydrated);
  const consumed = useRef(false);
  const lifecycle = useRef<ReturnType<typeof createInlinePresence> | null>(null);
  const registered = useRef<HTMLDivElement | null>(null);
  // The addon owns its own projected position: the frame publishes committed
  // boxes, and no component writes another component's transform.
  const [positions] = useState(() => createGroupPositions(group?.scope.transaction));
  const projection = useRef({ cm, present });
  projection.current = { cm, present };
  const plain = typeof children === "string" || typeof children === "number";
  useEffect(() => {
    const host = node.current;
    if (!host || !group) return;
    return group.attach(host, (from, to, revision, animate) => {
      const current = projection.current;
      const parameters = current.cm.parameters(bindMotionParameters(layoutCompact, "layout.move/position"));
      if (parameters.kind !== "layout") return;
      positions.commit({
        host: node,
        revision,
        cm: current.cm,
        boxes: new Map([[host, to]]),
        from: new Map([[host, from]]),
        available: animate,
        axis: "x",
      });
    });
  }, [group, node, positions]);
  committed(() => {
    const host = node.current;
    if (!host) return;
    if (registered.current !== host) {
      lifecycle.current?.dispose();
      lifecycle.current = createInlinePresence(host, group?.scope.transaction);
      registered.current = host;
    }
    const baseline = group?.scope ?? documentPresentation(host.ownerDocument);
    const visible = host.checkVisibility
      ? host.checkVisibility({ visibilityProperty: true, contentVisibilityAuto: true })
      : host.getClientRects().length > 0;
    const inherited =
      !visible ||
      Boolean(host.closest('[hidden],[inert],[aria-hidden="true"]')) ||
      !baseline.available() ||
      baseline.node?.current?.hasAttribute("data-starting-style");
    lifecycle.current?.commit({
      present,
      cm: inherited ? { ...cm, timeScale: 0 } : cm,
      enter: !consumed.current && !firstHydration.current && (group?.present ?? true) && !inherited,
      complete: () => {
        const entry = delivery.current;
        if (entry.present) return;
        if (entry.ready) entry.complete?.();
        else entry.pending = true;
      },
    });
    consumed.current = true;
    group?.request();
  });
  committed(
    () => () => {
      lifecycle.current?.dispose();
      lifecycle.current = null;
      registered.current = null;
      positions.dispose();
      group?.request();
    },
    [],
  );
  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={align}
      {...props}
      ref={ref}
      data-motion={cm.mode}
      data-ending-style={present ? undefined : ""}
      inert={!present || props.inert || undefined}
      aria-hidden={present ? props["aria-hidden"] : true}
      className={cn(inputGroupAddonVariants({ align }), className)}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        if ((event.target as HTMLElement).closest("button")) {
          return;
        }
        event.currentTarget.parentElement?.querySelector("input")?.focus();
      }}
    >
      {plain ? (
        typeof children === "number" ? (
          <GroupNumber value={children} />
        ) : (
          <GroupText value={children} />
        )
      ) : (
        children
      )}
    </div>
  );
}

const inputGroupButtonVariants = cva("flex items-center gap-2 text-sm shadow-none", {
  variants: {
    size: {
      xs: "h-6 gap-1 rounded-[calc(var(--radius)-5px)] px-2 has-[>svg]:px-2 [&>svg:not([class*='size-'])]:size-3.5",
      sm: "h-8 gap-1.5 rounded-md px-2.5 has-[>svg]:px-2.5",
      "icon-xs": "size-6 rounded-[calc(var(--radius)-5px)] p-0 has-[>svg]:p-0",
      "icon-sm": "size-8 p-0 has-[>svg]:p-0",
    },
  },
  defaultVariants: {
    size: "xs",
  },
});

export interface InputGroupButtonProps
  extends Omit<React.ComponentProps<typeof Button>, "size">,
    VariantProps<typeof inputGroupButtonVariants> {
  type?: "button" | "submit" | "reset";
}

/**
 * A button inside the frame. It sizes itself from the addon scale rather than the
 * page scale, so a clear button does not tower over a 36px field.
 *
 * It renders Button itself, so the composed action keeps Button's own
 * `data-slot="button"` and owners; a caller may retarget the slot (Combobox names
 * it `input-group-button`), but the group contract still points at Button's host.
 */
function InputGroupButton({
  className,
  type = "button",
  variant = "ghost",
  size = "xs",
  ...props
}: InputGroupButtonProps) {
  return (
    <Button
      type={type}
      variant={variant}
      size={size}
      className={(state) =>
        cn(inputGroupButtonVariants({ size }), typeof className === "function" ? className(state) : className)
      }
      {...props}
    />
  );
}

export interface InputGroupTextProps extends React.ComponentProps<"span"> {}

/** Display text in the frame; owns its foreground and its changed runs. */
function InputGroupText({ className, style, children, ...props }: InputGroupTextProps) {
  const { node } = useMotionHostRef<HTMLSpanElement>(props.ref);
  const cm = useCadenceMotion(node);
  const paint = useStateColor(node, cm, ["color"], { readability: "verified" });
  const plain = typeof children === "string" || typeof children === "number";
  return (
    <span
      data-slot="input-group-text"
      {...props}
      {...paint}
      data-motion={cm.mode}
      className={cn(
        "flex items-center gap-2 text-sm text-muted-foreground [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      style={{ ...paint.style, ...style }}
    >
      {plain ? (
        typeof children === "number" ? (
          <GroupNumber value={children} />
        ) : (
          <GroupText value={children} />
        )
      ) : (
        children
      )}
    </span>
  );
}

/** Only a known plain label supplies an independent changed-run owner. */
function GroupText({ value }: { value: string }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const group = useContext(Group);
  const entity = useRef({});
  const text = useTextPresentation(
    node,
    value,
    cm,
    entity.current,
    { characterStagger: false, stripGeometry: true, visible: group?.present ?? true },
    group?.scope.transaction,
  );
  return (
    <span ref={ref} data-slot="input-group-label" data-motion={cm.mode}>
      {text}
    </span>
  );
}

function GroupNumber({ value }: { value: number }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const group = useContext(Group);
  const entity = useRef({});
  const text = useNumberPresentation(
    node,
    value,
    cm,
    entity.current,
    { compact: true, visible: group?.present ?? true, retainEditedContent: true, cause: "independent" },
    group?.scope.transaction,
  );
  return (
    <span ref={ref} data-slot="input-group-number" data-motion={cm.mode}>
      {text}
    </span>
  );
}

export interface InputGroupInputProps extends React.ComponentProps<"input"> {}

/**
 * The control, stripped of its own chrome: `data-slot="input-group-control"` is
 * what the frame's `:has()` selectors watch for focus and invalid state. The
 * composition names its native element, so the editor stays an `<input>` and
 * never becomes a second, non-native editing surface.
 */
function InputGroupInput({ className, ...props }: InputGroupInputProps) {
  return (
    <Input
      data-slot="input-group-control"
      {...props}
      render={<input />}
      className={cn(
        "flex-1 rounded-none border-0 bg-transparent shadow-none focus-visible:ring-0 dark:bg-transparent",
        className,
      )}
    />
  );
}

export interface InputGroupTextareaProps extends React.ComponentProps<"textarea"> {}

function InputGroupTextarea({ className, ...props }: InputGroupTextareaProps) {
  return (
    <Textarea
      data-slot="input-group-control"
      {...props}
      className={cn(
        "flex-1 resize-none rounded-none border-0 bg-transparent py-3 shadow-none focus-visible:ring-0 dark:bg-transparent",
        className,
      )}
    />
  );
}

/** A focused editor owns its own box; a captured pointer or IME owns it too. */
function editor(host: HTMLElement | null) {
  if (!host) return false;
  const active = host.ownerDocument.activeElement;
  if (!active || !host.contains(active)) return false;
  return Boolean(active.closest("input,textarea,[contenteditable]:not([contenteditable=false])"));
}

/** Only a committed, editor-free frame is interpolated, and only when readable. */
function frameHeight(host: HTMLDivElement, reason: string, captured: number): GeometryDestination | null {
  if (reason !== "commit" || !host.isConnected || captured > 0) return null;
  if (editor(host)) return null;
  const box = naturalGeometry(host);
  const css = host.ownerDocument.defaultView?.getComputedStyle(host);
  if (!box || !css) return null;
  if (callerHeightClock(host, css)) return null;
  const min = boundedLength(css.minHeight) ?? 0;
  const max = boundedLength(css.maxHeight) ?? Number.POSITIVE_INFINITY;
  if (max < min) return null;
  return {
    height: {
      size: box.height,
      min,
      max,
      readable: host.scrollHeight <= Math.ceil(box.height),
      independent: true,
    },
  };
}

function boundedLength(value: string) {
  return /^\d+(?:\.\d+)?px$/.test(value) ? Number.parseFloat(value) : null;
}

/** A caller transition or animation on the block axis owns its own clock. */
function callerHeightClock(host: HTMLElement, css: CSSStyleDeclaration) {
  const family = css.transitionProperty.split(",").map((property) => property.trim());
  const times = css.transitionDuration.split(",").map(Number.parseFloat);
  if (
    family.some(
      (property, index) => (property === "all" || property === "height") && (times[index % times.length] ?? 0) > 0,
    )
  )
    return true;
  return (host.getAnimations?.() ?? [])
    .slice(0, motionLimits.collectionVisuals)
    .some((handle) =>
      ((handle.effect as KeyframeEffect | null)?.getKeyframes() ?? []).some((frame) => "height" in frame),
    );
}

export {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
  InputGroupTextarea,
  inputGroupAddonVariants,
  inputGroupButtonVariants,
};

"use client";

import { bindMotionParameters, motionMilliseconds, presenceInline } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { createMotionTransaction, type MotionLease } from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type InlinePresenceCommit = {
  present: boolean;
  enter: boolean;
  cm: CadenceMotion;
};

/** Entrance opacity only, on the original group host. Never writes a resting opacity. */
export function createInlineEntrance(node: HTMLElement) {
  const transaction = createMotionTransaction();
  const owner = transaction.register(node);
  let current: InlinePresenceCommit | null = null;
  let lease: MotionLease | null = null;
  let animation: Animation | null = null;
  let alive = true;
  let blocked = false;
  let generation = 0;
  let signature = "";
  const cancel = () => {
    generation++;
    animation?.cancel();
    animation = null;
    lease?.cancel();
    lease = null;
  };
  const settle = () => {
    cancel();
  };
  const callerOpacity = (css = node.ownerDocument.defaultView?.getComputedStyle(node)) => {
    if (!css) return false;
    const family = css.transitionProperty.split(",").map((property) => property.trim());
    const times = css.transitionDuration.split(",").map((time) => Number.parseFloat(time));
    return (
      family.some(
        (property, index) => ["all", "opacity"].includes(property) && (times[index % times.length] ?? 0) > 0,
      ) ||
      (node.getAnimations?.() ?? []).some(
        (handle) =>
          handle !== animation &&
          (handle.effect as KeyframeEffect | null)?.getKeyframes().some((frame) => "opacity" in frame),
      )
    );
  };
  const play = (from?: string, forceImmediate = false) => {
    const input = current;
    if (!alive || !input) return;
    if (!input.present) {
      settle();
      return;
    }
    const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
    if (parameters.kind !== "visual") return;
    const clock = parameters.opacity;
    const immediate = forceImmediate || blocked || clock.duration === 0;
    if (
      (immediate && input.present) ||
      !node.isConnected ||
      typeof node.animate !== "function" ||
      (input.present && node.contains(node.ownerDocument.activeElement))
    ) {
      settle();
      return;
    }
    const css = node.ownerDocument.defaultView?.getComputedStyle(node);
    if (!css || css.display === "none" || css.visibility === "hidden") {
      settle();
      return;
    }
    if (callerOpacity(css)) {
      settle();
      return;
    }
    const epoch = ++generation;
    const revision = transaction.revision("presence", input.present, node);
    let handle: Animation | null = null;
    lease = owner.begin(revision, ["opacity"], {}, () => handle?.cancel());
    if (!lease?.current()) return;
    const owned = lease;
    handle = node.animate([{ opacity: from ?? 0 }, { opacity: css.opacity }], {
      duration: motionMilliseconds(immediate ? 0 : Number(clock.duration)),
      delay: motionMilliseconds(immediate ? 0 : Number(clock.delay ?? 0)),
      easing: `cubic-bezier(${input.cm.scope.tokens.ease.out.join(",")})`,
      fill: "both",
    });
    animation = handle;
    void handle.finished.then(
      () => {
        if (
          !alive ||
          !node.isConnected ||
          epoch !== generation ||
          !owned.current() ||
          current?.present !== input.present
        )
          return;
        settle();
      },
      () => {},
    );
    if (immediate) handle.finish();
  };
  const interact = () => {
    if (current?.present) settle();
  };
  for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
    node.addEventListener(event, interact, true);
  const opacityStyle = () => {
    const style = node.style;
    return JSON.stringify([
      style.opacity,
      style.animation,
      /(?:^|,)\s*(?:all|opacity)\s*(?:,|$)/.test(style.transitionProperty) ? style.transition : "",
      Array.from(style)
        .filter((name) => name.startsWith("--") && !/^--(?:cadence-|motion-|ease-cadence)/.test(name))
        .map((name) => [name, style.getPropertyValue(name)]),
    ]);
  };
  let callerStyle = opacityStyle();
  const observer = new MutationObserver((records) => {
    const next = opacityStyle();
    // Scoped colour clocks and inherited Cadence tokens are another owned
    // family. Only potentially conflicting caller paint revokes this channel.
    if (
      (next !== callerStyle || records.some((record) => record.attributeName !== "style")) &&
      (current?.present || callerOpacity())
    )
      settle();
    callerStyle = next;
  });
  observer.observe(node, { attributes: true, attributeFilter: ["class", "style", "disabled", "aria-disabled"] });
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    blocked = environment.hidden || environment.immediate;
    if (blocked || (environment.reduced && animation && current?.cm.mode === "full")) {
      settle();
    }
  });
  return {
    commit(input: InlinePresenceCommit) {
      const previous = current;
      current = input;
      // Resolve the exact entrance clock on every committed policy, including native baselines.
      const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
      const clock = JSON.stringify(parameters);
      const retime = signature !== clock;
      signature = clock;
      const change = previous ? previous.present !== input.present : input.enter || !input.present;
      if (change) {
        const from = animation ? node.ownerDocument.defaultView?.getComputedStyle(node).opacity : undefined;
        cancel();
        play(from);
      } else if (input.cm.disabled || input.cm.timeScale === 0) {
        settle();
      } else if (retime && animation) {
        const from = node.ownerDocument.defaultView?.getComputedStyle(node).opacity;
        cancel();
        play(from);
      }
    },
    dispose() {
      alive = false;
      cancel();
      owner.dispose();
      observer.disconnect();
      unsubscribe();
      for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
        node.removeEventListener(event, interact, true);
    },
  };
}

"use client";

import { animateSingleValue, motionValue } from "motion/react";
import { labelGeometry } from "./label-layout";
import { bindMotionParameters, layoutCompact, motionLimits } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import type { MotionHostRef } from "./motion-ref";
import {
  createMotionTransaction,
  knownTextGeometry,
  type MotionLease,
  type MotionRevision,
  registerTextGeometry,
} from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type GroupPosition = { x: number; y: number; width: number; height: number; velocity?: number };

/** One scalar projection, separate from the control's native host/press layer.
 * The adapter supplies final boxes once; scalar callbacks never read layout. */
export function createGroupPositions(transaction = createMotionTransaction()) {
  const phase = motionValue(1);
  let target = new Map<HTMLElement, GroupPosition>();
  let origin = new Map<HTMLElement, GroupPosition>();
  const effects = new Map<HTMLElement, { animation: Animation; lease: MotionLease; dispose(): void }>();
  let revision: MotionRevision | null = null;
  let clock = "";
  let axis: "x" | "y" = "x";
  const sample = () =>
    new Map(
      [...target].map(([host, box]) => {
        const before = origin.get(host) ?? box;
        const p = Math.max(0, Math.min(1, phase.get()));
        return [
          host,
          {
            ...box,
            x: axis === "x" ? before.x + (box.x - before.x) * p : box.x,
            y: axis === "y" ? before.y + (box.y - before.y) * p : box.y,
            velocity: (box[axis] - before[axis]) * phase.getVelocity(),
          },
        ];
      }),
    );
  const cancel = () => {
    phase.stop();
    const previous = [...effects.values()];
    effects.clear();
    for (const effect of previous) effect.dispose();
  };
  const write = () => {
    const current = sample();
    for (const [host, effect] of effects) {
      const box = current.get(host),
        end = target.get(host);
      if (box && end && effect.lease.current())
        (effect.animation.effect as KeyframeEffect).setKeyframes({
          transform: `translate(${box.x - end.x}px,${box.y - end.y}px)`,
        });
    }
  };
  const off = phase.on("change", write);
  let unsubscribe = () => {};
  return {
    owns(animation: Animation) {
      return [...effects].some(
        ([host, effect]) =>
          effect.animation === animation &&
          effect.lease.current() &&
          (animation.effect as KeyframeEffect | null)?.target === host &&
          knownTextGeometry(animation, "full"),
      );
    },
    prepare() {
      const current = sample();
      cancel();
      return current;
    },
    commit(input: {
      host: MotionHostRef<HTMLElement>;
      revision: MotionRevision;
      cm: CadenceMotion;
      boxes: Map<HTMLElement, GroupPosition>;
      from: Map<HTMLElement, GroupPosition>;
      available: boolean;
      axis: "x" | "y";
    }) {
      const parameters = input.cm.parameters(bindMotionParameters(layoutCompact, "layout.move/position"));
      if (parameters.kind !== "layout") return;
      const nextClock = JSON.stringify([input.cm.mode, parameters.transition]);
      const same = revision === input.revision;
      const changedClock = clock !== nextClock;
      revision = input.revision;
      clock = nextClock;
      cancel();
      target = input.boxes;
      origin = input.from;
      axis = input.axis;
      unsubscribe();
      unsubscribe = input.host.current
        ? subscribeMotionEnvironment(input.host.current.ownerDocument, (environment) => {
            if (environment.hidden || environment.reduced || environment.immediate) {
              cancel();
              origin = target;
            }
          })
        : () => {};
      const visuals = new Set([...(input.host.current ? [input.host.current] : []), ...target.keys()]);
      if (
        !input.available ||
        input.cm.reduced ||
        parameters.transition.duration === 0 ||
        (same && !changedClock) ||
        !transaction.preflightVisuals(visuals)
      ) {
        origin = target;
        return;
      }
      for (const [host, box] of target) {
        const before = origin.get(host);
        if (!before || before[input.axis] === box[input.axis] || !host.animate) continue;
        const owner = transaction.register(host);
        const lease = owner.begin(input.revision, ["transform"], { collectionVisuals: visuals }, cancel);
        if (!lease) {
          owner.dispose();
          cancel();
          return;
        }
        const animation = host.animate({}, { duration: 0, fill: "both" });
        registerTextGeometry(animation, lease, input.cm.mode);
        effects.set(host, {
          animation,
          lease,
          dispose() {
            animation.cancel();
            lease.cancel();
            owner.dispose();
          },
        });
      }
      phase.jump(0);
      write();
      const rates = [...target].flatMap(([host, box]) => {
        const before = origin.get(host),
          delta = box[axis] - (before?.[axis] ?? box[axis]);
        return delta ? [(before?.velocity ?? 0) / delta] : [];
      });
      const rate = rates[0] ?? 0;
      const coherent = rates.every(
        (value) => Math.abs(value - rate) <= Number.EPSILON * Math.max(1, Math.abs(value), Math.abs(rate)),
      );
      if (effects.size)
        animateSingleValue(phase, 1, {
          ...parameters.transition,
          velocity: coherent ? Math.max(0, rate) : 0,
          onComplete: cancel,
        });
    },
    settle() {
      cancel();
      origin = target;
    },
    dispose() {
      cancel();
      off();
      unsubscribe();
      target.clear();
      origin.clear();
    },
  };
}

/** Exact cross-axis native stretch, caused by this scope's leased direct rule.
 * Neither a matching attribute nor an unrelated dimension engine grants it. */
export function groupStretchEcho(
  host: HTMLElement,
  source: HTMLElement,
  target: HTMLElement,
  axis: "width" | "height",
  owns: (animation: Animation) => boolean,
) {
  if (source.parentElement !== host || (target !== host && target.parentElement !== host)) return false;
  const parent = getComputedStyle(host),
    css = getComputedStyle(source);
  if (
    !parent.display.includes("flex") ||
    !(
      (parent.flexDirection.startsWith("row") && axis === "height") ||
      (parent.flexDirection.startsWith("column") && axis === "width")
    )
  )
    return false;
  const vertical = axis === "height";
  const content =
    (vertical ? host.clientHeight : host.clientWidth) -
    Number.parseFloat(parent[vertical ? "paddingTop" : "paddingLeft"]) -
    Number.parseFloat(parent[vertical ? "paddingBottom" : "paddingRight"]);
  const extent =
    (vertical ? source.offsetHeight : source.offsetWidth) +
    Number.parseFloat(css[vertical ? "marginTop" : "marginLeft"]) +
    Number.parseFloat(css[vertical ? "marginBottom" : "marginRight"]);
  if (!Number.isFinite(content) || !Number.isFinite(extent) || Math.round(content) !== Math.round(extent)) return false;
  if (target === host) return true;
  const child = getComputedStyle(target);
  const alignment = child.alignSelf === "auto" ? parent.alignItems : child.alignSelf;
  if (
    target.dataset.slot !== "button-group-segment" ||
    target.computedStyleMap?.().get(axis)?.toString() !== "auto" ||
    alignment !== "stretch" ||
    ["absolute", "fixed"].includes(child.position)
  )
    return false;
  const expected =
    content -
    Number.parseFloat(child[vertical ? "marginTop" : "marginLeft"]) -
    Number.parseFloat(child[vertical ? "marginBottom" : "marginRight"]);
  if (!Number.isFinite(expected) || Math.round(expected) !== (vertical ? target.offsetHeight : target.offsetWidth))
    return false;
  const handles = target.getAnimations();
  return (
    handles.length <= motionLimits.collectionVisuals &&
    handles.every((animation) => {
      if (owns(animation)) return true;
      const frames = (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [];
      return (
        frames.length <= motionLimits.collectionVisuals &&
        frames.every(
          (frame) =>
            !Object.keys(frame).some((key) =>
              /^(?:width|height|minWidth|maxWidth|minHeight|maxHeight|flexBasis|transform|translate|scale|rotate|padding|gap)$/.test(
                key,
              ),
            ),
        )
      );
    })
  );
}

/** Fixed outgoing paint and local FLIP share a proven untransformed mapping.
 * Caller/native geometry engines are audited by the committed constraint owner. */
export function groupMapping(host: HTMLElement) {
  let count = 0;
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    if (++count > motionLimits.collectionVisuals) return false;
    const css = getComputedStyle(node);
    if (
      css.transform !== "none" ||
      css.translate !== "none" ||
      css.rotate !== "none" ||
      css.scale !== "none" ||
      css.perspective !== "none" ||
      css.offsetPath !== "none" ||
      !["normal", "1"].includes(css.zoom) ||
      css.writingMode !== "horizontal-tb"
    )
      return false;
  }
  return true;
}

export function buttonGroupGeometry(
  host: HTMLElement,
  orientation: string,
  clips?: Map<HTMLElement, { width: number; height: number }>,
) {
  const axis = orientation === "vertical" ? "height" : "width";
  if (host.children.length + 1 > motionLimits.collectionVisuals) return null;
  for (const layer of host.children) {
    if (layer.hasAttribute("data-ending-style")) continue;
    const member = layer.firstElementChild;
    for (const node of [layer, member]) {
      if (!(node instanceof HTMLElement)) continue;
      const css = getComputedStyle(node);
      const properties = css.transitionProperty.split(",").map((name) => name.trim());
      const times = css.transitionDuration.split(",").map(Number.parseFloat);
      const dimensional = /^(all|width|height|min-width|max-width|min-height|max-height|padding|gap|flex-basis)$/;
      if (
        properties.some((name, index) => dimensional.test(name) && (times[index % times.length] ?? 0) > 0) ||
        node
          .getAnimations()
          .some(
            (animation) =>
              !knownTextGeometry(animation, "full") &&
              (animation.effect as KeyframeEffect | null)
                ?.getKeyframes()
                .some((frame) =>
                  Object.keys(frame).some((name) =>
                    /^(width|height|minWidth|maxWidth|minHeight|maxHeight|padding|gap|flexBasis)$/.test(name),
                  ),
                ),
          )
      )
        return null;
    }
    if (layer instanceof HTMLElement) {
      const size = layer.computedStyleMap?.().get(axis)?.toString() ?? layer.style[axis];
      if (size && !/^(auto|none|fit-content|max-content|min-content|0|(?:\d+(?:\.\d+)?|\.\d+)px)$/.test(size))
        return null;
    }
  }
  const value = labelGeometry(host, host, true);
  if (!value) return null;
  const target = value[axis];
  if (!target) return null;
  // A shrink-wrapped parent's current extent echoes this very group. It is
  // not an independent maximum that may truncate the captured shrink origin.
  // Actual native min/max constraints remain authoritative over the overlay.
  const constraints = [`min-${axis}`, `max-${axis}`].map(
    (name) => host.computedStyleMap?.().get(name)?.toString() ?? host.style.getPropertyValue(name),
  );
  if (constraints.some((value) => value && !/^(none|auto|0|(?:\d+(?:\.\d+)?|\.\d+)px)$/.test(value))) return null;
  const maximum = constraints[1];
  let clipped = false;
  const box = host.getBoundingClientRect();
  const nextClips = new Map<HTMLElement, { width: number; height: number }>();
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    const css = getComputedStyle(node);
    if (!/(hidden|clip|auto|scroll)/.test(`${css.overflowX} ${css.overflowY}`) && !css.contain.includes("paint"))
      continue;
    const clip = node.getBoundingClientRect(),
      before = clips?.get(node);
    nextClips.set(node, { width: clip.width, height: clip.height });
    // A before/after native allocation receipt distinguishes a fixed outer
    // preview/viewport clip from an intrinsic clip that echoes this group.
    // The group shell itself must never introduce an intermediate clip.
    clipped ||=
      node === host ||
      before?.[axis] !== clip[axis] ||
      box.left < clip.left ||
      box.right > clip.right ||
      box.top < clip.top ||
      box.bottom > clip.bottom;
  }
  if (clips) {
    clips.clear();
    for (const [node, box] of nextClips) clips.set(node, box);
  }
  const minimum = constraints[0]?.endsWith("px") ? Number.parseFloat(constraints[0]) : 0;
  return {
    [axis]: {
      ...target,
      min: Math.max(minimum, clipped ? (target.min ?? target.size) : 0),
      max: maximum?.endsWith("px") ? Number.parseFloat(maximum) : undefined,
    },
  };
}

"use client";

import { type GeometryDestination, naturalGeometry } from "./measured-geometry";
import { motionLimits } from "./motion";
import { knownTextGeometry } from "./motion-transaction";
import { nativeTextContext, selectedTextContext } from "./text-layout";

/** Passive constraints are distinct from a committed display revision. */
export function observeLabelConstraints(host: HTMLElement, content: HTMLElement, settle: () => void) {
  const view = host.ownerDocument.defaultView;
  const chain: HTMLElement[] = [];
  for (
    let node: HTMLElement | null = host;
    node && chain.length < motionLimits.collectionVisuals;
    node = node.parentElement
  )
    chain.push(node);
  let parent = host.parentElement;
  while (parent && getComputedStyle(parent).display === "contents") parent = parent.parentElement;
  let alive = true,
    ready = false,
    signature = "",
    width = 0,
    vertical = false;
  let frame: number | null = null;
  const dimension =
    /^(?:all|width|height|min-width|max-width|min-height|max-height|transform|translate|scale|rotate|padding|gap)$/;
  const paint =
    /^(?:color|background|border.*color|box-shadow|text-shadow|opacity|filter|fill|stroke|transition|--(?:cadence-|motion-|ease-))/;
  const read = () =>
    JSON.stringify(
      chain.map((node) => {
        const geometryClock = node.style.transitionProperty.split(",").some((name) => dimension.test(name.trim()));
        return [
          node.className,
          node.hidden,
          node.dir,
          node.getAttribute("contenteditable"),
          node.hasAttribute("inert"),
          node.getAttribute("aria-hidden"),
          Array.from(node.style)
            .filter((name) => !paint.test(name) || (geometryClock && name.startsWith("transition")))
            .map((name) => [name, node.style.getPropertyValue(name)]),
        ];
      }),
    );
  const refresh = () => {
    signature = read();
    width = parent?.getBoundingClientRect().width ?? 0;
    vertical = !!parent && /^(vertical|sideways)/.test(getComputedStyle(parent).writingMode);
    mutations.takeRecords();
    ready = true;
  };
  const cancel = () => {
    if (!alive) return;
    settle();
    refresh();
    if (frame !== null) view?.cancelAnimationFrame(frame);
    frame = null;
  };
  const mutations = new MutationObserver(() => {
    if (alive && ready && signature !== read()) cancel();
  });
  for (const node of chain)
    mutations.observe(node, {
      attributes: true,
      attributeFilter: ["class", "style", "hidden", "dir", "contenteditable", "inert", "aria-hidden"],
    });
  const resize = new ResizeObserver((entries) => {
    if (!alive || !ready || !parent) return;
    const box = entries.find((entry) => entry.target === parent)?.borderBoxSize?.[0];
    if (!box || (vertical ? box.blockSize : box.inlineSize) !== width) cancel();
  });
  if (parent) resize.observe(parent, { box: "border-box" });
  const audit = () => {
    frame = null;
    if (!alive) return;
    const handles = [host, content].flatMap((node) => node.getAnimations?.() ?? []);
    const owned = handles.some((animation) => knownTextGeometry(animation, "full"));
    if (!owned) return;
    const unsafe =
      handles.length > motionLimits.collectionVisuals ||
      handles.some((animation) => {
        if (knownTextGeometry(animation, "full")) return false;
        const keys = (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [];
        return (
          keys.length > motionLimits.collectionVisuals ||
          keys.some((key) =>
            Object.keys(key).some((name) =>
              dimension.test(name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)),
            ),
          )
        );
      });
    if (unsafe) {
      cancel();
      return;
    }
    frame = view?.requestAnimationFrame(audit) ?? null;
  };
  return {
    prepare(semantic: boolean) {
      if (!semantic && ready && signature !== read()) cancel();
    },
    commit() {
      refresh();
      if (frame === null) audit();
    },
    dispose() {
      alive = false;
      mutations.disconnect();
      resize.disconnect();
      if (frame !== null) view?.cancelAnimationFrame(frame);
    },
  };
}

/** Measure one real label at destination width; never size interactive rich content. */
export function labelGeometry(host: HTMLElement, content: HTMLElement, focusSafe = false): GeometryDestination | null {
  const css = getComputedStyle(host),
    typed = host.computedStyleMap?.();
  const natural = naturalGeometry(host);
  const box = host.getBoundingClientRect();
  if (
    !natural ||
    css.boxSizing !== "border-box" ||
    nativeTextContext(host) ||
    host.closest('[hidden],[inert],[aria-hidden="true"]') ||
    selectedTextContext(host) ||
    (!focusSafe && host.contains(host.ownerDocument.activeElement)) ||
    css.writingMode !== "horizontal-tb" ||
    !["flex", "inline-flex", "block", "inline-block"].includes(css.display)
  )
    return null;
  let parent = host.parentElement;
  while (parent && getComputedStyle(parent).display === "contents") parent = parent.parentElement;
  const parentCSS = parent && getComputedStyle(parent);
  // Percentage/ratio and horizontal flex allocations keep their native owner.
  if (css.aspectRatio !== "auto" || (parentCSS?.display.includes("flex") && parentCSS.flexDirection.startsWith("row")))
    return null;
  const width = typed?.get("width")?.toString();
  const height = typed?.get("height")?.toString();
  const crossAlignment = css.alignSelf === "auto" ? parentCSS?.alignItems : css.alignSelf;
  const intrinsicColumn =
    parentCSS?.display.includes("flex") &&
    parentCSS.flexDirection.startsWith("column") &&
    crossAlignment &&
    !["normal", "stretch"].includes(crossAlignment);
  const intrinsicWidth =
    width === "fit-content" ||
    width === "max-content" ||
    (width === "auto" && (css.display.startsWith("inline-") || intrinsicColumn));
  let clipped = false;
  for (let node: HTMLElement | null = content, depth = 0; node; node = node.parentElement, depth++) {
    if (depth >= motionLimits.collectionVisuals) return null;
    const style = getComputedStyle(node);
    const properties = style.transitionProperty.split(",").map((property) => property.trim());
    const times = style.transitionDuration.split(",").map(Number.parseFloat);
    if (
      properties.some(
        (property, index) =>
          /^(all|width|height|min-width|max-width|min-height|max-height|transform|translate|scale|rotate|padding|gap)$/.test(
            property,
          ) && (times[index % times.length] ?? 0) > 0,
      )
    )
      return null;
    if (
      node
        .getAnimations()
        .some(
          (animation) =>
            !knownTextGeometry(animation, "full") &&
            (animation.effect as KeyframeEffect | null)
              ?.getKeyframes()
              .some((frame) =>
                Object.keys(frame).some((key) =>
                  /^(width|height|minWidth|maxWidth|minHeight|maxHeight|transform|translate|scale|rotate|padding|gap)$/.test(
                    key,
                  ),
                ),
              ),
        )
    )
      return null;
    if (style.scale !== "none" || style.rotate !== "none" || !["normal", "1"].includes(style.zoom)) return null;
    if (style.transform !== "none") {
      const matrix = new DOMMatrixReadOnly(style.transform);
      if (!matrix.is2D || matrix.a !== 1 || matrix.d !== 1 || matrix.b !== 0 || matrix.c !== 0) return null;
    }
    if (/(hidden|clip|auto|scroll)/.test(`${style.overflowX} ${style.overflowY}`) || style.contain.includes("paint"))
      clipped = true;
  }
  const contentBox = naturalGeometry(content);
  if (getComputedStyle(content).boxSizing !== "border-box") return null;
  if (!contentBox) return null;
  const destination: GeometryDestination = {};
  // Growing paint remains fully visible only in existing visible overflow.
  if (intrinsicWidth)
    destination.width = {
      size: box.width,
      min: clipped ? box.width : 0,
      max: Math.max(box.width, parent ? (naturalGeometry(parent)?.width ?? box.width) : box.width),
      readable: true,
      independent: true,
    };
  if (height === "auto")
    destination.height = {
      size: box.height,
      min: box.height,
      max: Math.max(box.height, host.ownerDocument.defaultView?.innerHeight ?? box.height),
      readable: true,
      independent: true,
    };
  return destination;
}

type Interval = [number, number];
const contexts = new WeakMap<Document, CanvasRenderingContext2D>();

/** Prove the complete neutral foreground path over its actual static backdrop.
 * Unknown colour spaces, caller surfaces and parent colour owners stay immediate. */
export function labelColourReadable(node: Element) {
  const view = node.ownerDocument.defaultView;
  if (!view || typeof view.CanvasRenderingContext2D === "undefined") return false;
  let context = contexts.get(node.ownerDocument);
  if (!context) {
    const canvas = node.ownerDocument.createElement("canvas");
    canvas.width = canvas.height = 1;
    context = canvas.getContext("2d", { willReadFrequently: true }) ?? undefined;
    if (!context) return false;
    contexts.set(node.ownerDocument, context);
  }
  const neutral = (value: string) => {
    if (!view.CSS.supports("color", value)) return null;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = value;
    context.fillRect(0, 0, 1, 1);
    const [r = 0, g = 0, b = 0, a = 0] = context.getImageData(0, 0, 1, 1).data;
    return a && Math.max(r, g, b) !== Math.min(r, g, b) ? null : { value: r / 255, alpha: a / 255 };
  };
  const ancestry: Element[] = [];
  for (let current: Element | null = node; current; current = current.parentElement) {
    if (ancestry.length >= motionLimits.collectionVisuals) return false;
    const css = view.getComputedStyle(current);
    if (css.backgroundImage !== "none" || css.opacity !== "1" || css.filter !== "none" || css.mixBlendMode !== "normal")
      return false;
    if (current !== node && current.getAttribute("data-cadence-color")?.split(",").includes("color")) return false;
    if (
      current !== node &&
      current
        .getAnimations()
        .some((animation) =>
          (animation.effect as KeyframeEffect | null)
            ?.getKeyframes()
            .some((frame) => "backgroundColor" in frame || "color" in frame),
        )
    )
      return false;
    ancestry.push(current);
  }
  let surface: number | null = null;
  for (const current of ancestry.reverse()) {
    const colour = neutral(view.getComputedStyle(current).backgroundColor);
    if (!colour) return false;
    if (surface === null && colour.alpha !== 1) {
      if (colour.alpha === 0) continue;
      return false;
    }
    surface = colour.value * colour.alpha + (surface ?? 0) * (1 - colour.alpha);
  }
  if (surface === null) return false;
  const values = [view.getComputedStyle(node).color];
  for (const animation of node.getAnimations()) {
    if (!("transitionProperty" in animation) || animation.transitionProperty !== "color") continue;
    for (const frame of (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [])
      if (typeof frame.color === "string") values.push(frame.color);
  }
  const inks: number[] = [];
  for (const value of new Set(values)) {
    const colour = neutral(value);
    if (!colour) return false;
    inks.push(colour.value * colour.alpha + surface * (1 - colour.alpha));
  }
  const interval: Interval = [Math.min(...inks), Math.max(...inks)];
  if (interval[0] <= surface && interval[1] >= surface) return false;
  const luminance = (value: number) => (value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
  const low = luminance(interval[1] < surface ? interval[1] : surface);
  const high = luminance(interval[1] < surface ? surface : interval[0]);
  return (high + 0.05) / (low + 0.05) >= 4.5;
}

